/* GuroPrep JHS Mathematics (Grades 7–10). Load after the core helpers (src/math/skills.js, src/english/generators.js for mcq/toItem). Wrap these files in one block scope, as the prototype does. */
/* ===================== JHS Mathematics: Algebra ===================== */
const eq=(l,rr)=>l+' = '+rr;
const fr2=(n,d)=>qs(qn(n,d));
/* ---------- G7 ---------- */
J.varconst={fam:'j_alg',instr:'Answer each item about the expression.',g:(r,L)=>{const a=nz(r,-9,9),b=nz(r,-9,9),c=nz(r,-20,20);const vs=shuf(r,['x','y','m','n','a','b']).slice(0,2);const e=`${mono(a,{[vs[0]]:L==='E'?2:1})}${b<0?' '+MN+' ':' + '}${mono(Math.abs(b),{[vs[1]]:1})}${c<0?' '+MN+' ':' + '}${Math.abs(c)}`;
  return ITEM(`In ${e}, name the variables, the constant, and the coefficient of ${vs[0]}${L==='E'?'²':''}.`,`variables: ${vs[0]}, ${vs[1]}; constant: ${sn(c)}; coefficient of ${vs[0]}${L==='E'?'²':''}: ${sn(a)}`)}};
J.evalexpr={fam:'j_alg',instr:'Evaluate each expression for the given values.',work:true,g:(r,L)=>{const x=L==='F'?ri(r,1,9):nz(r,-6,6),y=L==='F'?ri(r,1,9):nz(r,-6,6);const a=ri(r,2,6),b=ri(r,2,9),c=ri(r,1,15);const T=L==='F'?[0,1]:L==='C'?[1,2,3]:[2,3,4];const t=pick(r,T);
  const E=[[`${a}x + ${c}`,a*x+c],[`${a}x ${MN} ${b}y`,a*x-b*y],[`x² + ${b}y`,x*x+b*y],[`${a}x² ${MN} ${b}x + ${c}`,a*x*x-b*x+c],[`(x + y)² ${MN} ${a}xy`,(x+y)**2-a*x*y]][t];return ITEM(`${E[0]}, when x = ${sn(x)}${t>=1?` and y = ${sn(y)}`:''}`.replace(/ and y = \S+$/,t===3?'':`$&`),sn(E[1]))}};
const TR=[[k=>`the sum of a number and ${k}`,k=>`n + ${k}`],[k=>`${k} less than a number`,k=>`n ${MN} ${k}`],[k=>`the product of ${k} and a number`,k=>`${k}n`],[k=>`a number divided by ${k}`,k=>`n/${k}`],[k=>`twice a number decreased by ${k}`,k=>`2n ${MN} ${k}`],[k=>`${k} times the sum of a number and 2`,k=>`${k}(n + 2)`],[k=>`the square of a number increased by ${k}`,k=>`n² + ${k}`],[k=>`${k} more than three times a number`,k=>`3n + ${k}`],[k=>`the difference between a number and ${k}`,k=>`n ${MN} ${k}`],[k=>`half of a number plus ${k}`,k=>`n/2 + ${k}`]];
J.translate={fam:'j_alg',instr:'Translate each phrase into an algebraic expression. Use n for the number.',g:(r,L)=>{const i=ri(r,0,TR.length-1),k=ri(r,3,12);const ph=TR[i][0](k),ex=TR[i][1](k);
  if(L==='F'){const others=[...new Set(shuf(r,TR.filter((_,j)=>j!==i)).map(t=>t[1](k)))].filter(x=>x!==ex).slice(0,2);return mcq(r,`Which expression means "${ph}"?`,ex,others)}if(L==='E'&&r()<.5)return ITEM(`Write a phrase for the expression ${ex}.`,ph+' (other wordings are fine)');return ITEM(`"${cap(ph)}"`,ex)}};
J.model={fam:'j_alg',instr:'Write an algebraic expression for each situation.',g:(r,L)=>{const n1=nm(r),n2=pick(r,NAMES.filter(x=>x!==n1));const k=ri(r,2,5),c=pick(r,[10,20,25,50,100]);const X=[[`${n1} has x pesos. ${n2} has ₱${c} more than ${k} times as much. How much does ${n2} have?`,`${k}x + ${c}`],[`A rectangle is x cm wide. Its length is ${k} cm more than its width. Write its perimeter.`,`2x + 2(x + ${k}) = 4x + ${2*k}`],[`A load costs ₱x. ${n1} buys ${k} loads and pays with ₱${fmt(c*10)}. Write the change.`,`${fmt(c*10)} ${MN} ${k}x`],[`The ages of ${n1} and ${n2} add up to ${c}. ${n1} is x years old. How old is ${n2}?`,`${c} ${MN} x`],[`A tricycle ride costs ₱${c} plus ₱${k} per kilometer. Write the cost for x kilometers.`,`${c} + ${k}x`],[`A number x is doubled, then ${k} is subtracted, and the result is squared.`,`(2x ${MN} ${k})²`]];return ITEM(...pick(r,L==='F'?X.slice(0,4):X))}};
J.propeq={fam:'j_alg',instr:'Name the property of equality shown.',g:(r,L)=>{const x=ri(r,2,12),a=ri(r,2,9),b=ri(r,2,9);const P=[[`If x = ${x}, then x + ${a} = ${x} + ${a}.`,'Addition Property of Equality'],[`If x + ${a} = ${x+a}, then x = ${x+a} ${MN} ${a}.`,'Subtraction Property of Equality'],[`If x/${a} = ${b}, then x = ${b} × ${a}.`,'Multiplication Property of Equality'],[`If ${a}x = ${a*b}, then x = ${a*b} ÷ ${a}.`,'Division Property of Equality'],[`${x} = ${x}`,'Reflexive Property'],[`If y = ${x}, then ${x} = y.`,'Symmetric Property'],[`If a = b and b = ${x}, then a = ${x}.`,'Transitive Property'],[`If y = ${a} and x + y = ${a+b}, then x + ${a} = ${a+b}.`,'Substitution Property']];
  const p=pick(r,L==='F'?P.slice(0,4):P);const no=shuf(r,P.filter(z=>z[1]!==p[1]).map(z=>z[1])).slice(0,3);return mcq(r,p[0],p[1],no)}};
const FORMS=[['P = 2l + 2w','w','w = (P − 2l)/2'],['A = ½bh','h','h = 2A/b'],['d = rt','t','t = d/r'],['I = Prt','r','r = I/(Pt)'],['V = lwh','h','h = V/(lw)'],['C = 2πr','r','r = C/(2π)'],['F = (9/5)C + 32','C','C = (5/9)(F − 32)'],['y = mx + b','m','m = (y − b)/x'],['A = ½(b₁ + b₂)h','h','h = 2A/(b₁ + b₂)'],['P = a + b + c','c','c = P − a − b'],['A = lw','l','l = A/w'],['S = 180(n − 2)','n','n = S/180 + 2']];
J.formula={fam:'j_alg',instr:'Solve each formula for the variable asked.',work:true,pool:L=>(L==='F'?FORMS.filter((_,i)=>[1,2,4,9,10,3].includes(i)):FORMS).map(f=>({q:`Solve ${f[0]} for ${f[1]}.`,a:f[2]}))};
J.writeeq={fam:'j_alg',instr:'Write an equation for each sentence. Use n for the number. Then solve it.',work:true,g:(r,L)=>{const n=ri(r,1,15),a=ri(r,2,6),b=ri(r,1,20);const S=[[`A number increased by ${b} is ${n+b}.`,`n + ${b} = ${n+b}`],[`${a} times a number is ${a*n}.`,`${a}n = ${a*n}`],[`${b} more than ${a} times a number is ${a*n+b}.`,`${a}n + ${b} = ${a*n+b}`],[`A number divided by ${a} is ${n}.`,`n/${a} = ${n}`],[`Twice a number decreased by ${b} is ${2*n-b}.`,`2n ${MN} ${b} = ${sn(2*n-b)}`],[`${a} times the sum of a number and ${b} is ${a*(n+b)}.`,`${a}(n + ${b}) = ${a*(n+b)}`]];const s=pick(r,L==='F'?S.slice(0,3):L==='C'?S.slice(1,5):S.slice(2));return ITEM(s[0],`${s[1]}; n = ${s[0].startsWith('A number divided')?n*a:n}`)}};
J.solve1={fam:'j_alg',instr:'Find the value of the unknown.',work:true,g:(r,L)=>{const x=ri(r,0,L==='F'?15:30),a=ri(r,2,9),b=ri(r,1,25);const T=L==='F'?[0,1,2]:L==='C'?[2,3,4]:[4,5,6];const t=pick(r,T);let s;
  switch(t){case 0:s=`x + ${b} = ${x+b}`;break;case 1:s=`x ${MN} ${b} = ${sn(x-b)}`;break;case 2:s=`${a}x = ${a*x}`;break;case 3:s=`x/${a} = ${x}`;break;case 4:s=`${a}x + ${b} = ${a*x+b}`;break;case 5:s=`${a}x ${MN} ${b} = ${sn(a*x-b)}`;break;default:s=`${a}(x + ${b}) = ${a*(x+b)}`}
  if(t===3)return ITEM(s,`x = ${x*a}`);return ITEM(s,`x = ${x}`)}};
J.barmodel={fam:'j_alg',instr:'Write the equation shown by the bar model, then find the unknown.',work:true,g:(r,L)=>{const x=ri(r,2,20),k=ri(r,2,L==='F'?3:5),b=ri(r,0,L==='F'?0:15);const whole=k*x+b;const parts=Array(k).fill('[ x ]').join('')+(b?`[ ${b} ]`:'');
  return ITEM(`Bar model: ${parts} — the whole bar is ${whole}.`,`${k}x${b?' + '+b:''} = ${whole}; x = ${x}`)}};
J.formulaprob={fam:'j_alg',instr:'Use the formula to solve. Show your solution.',work:true,g:(r,L)=>{const k=ri(r,0,L==='F'?2:4);
  if(k===0){const l=ri(r,5,30),w=ri(r,3,l);return ITEM(`Use P = 2l + 2w. A garden is ${l} m long and ${w} m wide. How much fencing goes around it?`,`P = 2(${l}) + 2(${w}) = ${2*l+2*w} m`)}
  if(k===1){const C=pick(r,[0,10,20,25,30,35,40,100]);return ITEM(`Use F = (9/5)C + 32. Convert ${C}°C to °F.`,`F = (9/5)(${C}) + 32 = ${dn(C*9/5+32)}°F`)}
  if(k===2){const b1=ri(r,4,12),b2=ri(r,b1+1,20),h=ri(r,2,10);return ITEM(`Use A = ½(b₁ + b₂)h. A trapezoid has bases ${b1} cm and ${b2} cm and height ${h} cm. Find its area.`,`A = ½(${b1} + ${b2})(${h}) = ${dn((b1+b2)*h/2)} sq. cm`)}
  if(k===3){const l=ri(r,6,20),P=2*l+2*ri(r,3,l-1);return ITEM(`A rectangle has perimeter ${P} cm and length ${l} cm. Use P = 2l + 2w to find its width.`,`w = (P − 2l)/2 = (${P} − ${2*l})/2 = ${(P-2*l)/2} cm`)}
  const P=pick(r,[5000,10000,20000]),rt=pick(r,[2,4,5]),I=P*rt/100*ri(r,2,4);return ITEM(`Use I = Prt. ₱${fmt(P)} earned ₱${fmt(I)} simple interest at ${rt}% a year. For how many years was it saved?`,`t = I/(Pr) = ${fmt(I)} ÷ (${fmt(P)} × ${dn(rt/100)}) = ${I/(P*rt/100)} years`)}};
/* ---------- G8 polynomials ---------- */
const VV=['x','y','a','b','m'];
J.monoaddsub={fam:'j_alg',instr:'Simplify by combining like terms.',g:(r,L)=>{const v=pick(r,VV.slice(0,3)),e=ri(r,1,3);const a=nz(r,-12,12),b=nz(r,-12,12);if(L==='F')return ITEM(`${mono(a,{[v]:e})} + ${a<0&&0?'':''}${b<0?'('+mono(b,{[v]:e})+')':mono(b,{[v]:e})}`,mono(a+b,{[v]:e}));
  if(L==='C'){const c=nz(r,-9,9);return ITEM(`${mono(a,{x:2,y:1})} ${MN} ${b<0?'('+mono(b,{x:2,y:1})+')':mono(b,{x:2,y:1})} + ${c<0?'('+mono(c,{x:2,y:1})+')':mono(c,{x:2,y:1})}`,mono(a-b+c,{x:2,y:1}))}
  const p=[nz(r,-6,6),ri(r,-9,9),ri(r,-9,9)],q=[nz(r,-6,6),ri(r,-9,9),ri(r,-9,9)];const add=r()<.5;const o=p.map((x,i)=>add?x+q[i]:x-q[i]);return ITEM(`(${poly(p)}) ${add?'+':MN} (${poly(q)})`,poly(o))}};
J.monomuldiv={fam:'j_alg',instr:'Simplify. Use the laws of exponents.',g:(r,L)=>{const a=nz(r,-6,6),b=nz(r,-6,6);const e1=ri(r,1,5),e2=ri(r,1,5),f1=ri(r,0,3),f2=ri(r,1,3);const t=ri(r,0,L==='F'?1:3);
  if(t===0)return ITEM(`(${mono(a,{x:e1,y:f1})})(${mono(b,{x:e2,y:f2})})`,mono(a*b,{x:e1+e2,y:f1+f2}));
  if(t===1){const A=a*b;return ITEM(`(${mono(A,{x:e1+e2,y:f1+f2})}) ÷ (${mono(a,{x:e1,y:f1})})`,mono(b,{x:e2,y:f2}))}
  if(t===2){const k=ri(r,2,3),c=pick(r,[1,2,3,-2]);return ITEM(`(${mono(c,{x:e1,y:f2})})${sup(k)}`,mono(c**k,{x:e1*k,y:f2*k}))}
  return ITEM(`x${sup(e1)} · x${sup(e2)} ÷ x${sup(Math.min(e1,e2))}`,mono(1,{x:Math.max(e1,e2)})+(Math.max(e1,e2)===0?'':''))}};
J.polymul={fam:'j_alg',instr:'Find each product.',work:true,g:(r,L)=>{const t=L==='F'?0:L==='C'?pick(r,[0,1,1]):pick(r,[1,2,2]);
  if(t===0){const k=nz(r,-6,6),e=ri(r,1,2);const p=[nz(r,-5,5),ri(r,-9,9)];if(!p[1])p[1]=3;const o=p.map(x=>x*k).concat(Array(e).fill(0));return ITEM(`${mono(k,{x:e})}(${poly(p)})`,poly(o))}
  if(t===1){const a=pick(r,[1,1,2,3,-1]),b=nz(r,-9,9),c=pick(r,[1,1,2,-2]),d=nz(r,-9,9);return ITEM(`${bin(a,b)}${bin(c,d)}`,poly(pmul([a,b],[c,d])))}
  const a=nz(r,-6,6),p=[1,nz(r,-5,5),nz(r,-9,9)];return ITEM(`${bin(1,a)}(${poly(p)})`,poly(pmul([1,a],p)))}};
J.specprod={fam:'j_alg',instr:'Use special products to find each product.',g:(r,L)=>{const a=pick(r,L==='F'?[1]:[1,1,2,3]),b=ri(r,1,12),t=ri(r,0,L==='E'?3:2);const v=pick(r,['x','y','m']);
  if(t===0)return ITEM(`${bin(a,b,v)}²`,poly([a*a,2*a*b,b*b],v));if(t===1)return ITEM(`${bin(a,-b,v)}²`,poly([a*a,-2*a*b,b*b],v));if(t===2)return ITEM(`${bin(a,b,v)}${bin(a,-b,v)}`,poly([a*a,0,-b*b],v));const c=ri(r,1,4);return ITEM(`${bin(1,c,v)}³`,poly([1,3*c,3*c*c,c*c*c],v))}};
J.factor={fam:'j_alg',instr:'Factor completely.',work:true,g:(r,L)=>{const T=L==='F'?[0,1,2]:L==='C'?[1,2,3,4]:[2,3,4,5,6];const t=pick(r,T);const v='x';
  if(t===0){const g=ri(r,2,9),p=ri(r,2,7),q=nz(r,-9,9);if(gcd(p,q)!==1)return J.factor.g(r,L);return ITEM(poly([g*p,g*q,0]),`${g}x${bin(p,q)}`,peq(pmul([g,0],[p,q]),[g*p,g*q,0]))}
  if(t===1){const b=ri(r,1,12);return ITEM(poly([1,0,-b*b]),`${bin(1,b)}${bin(1,-b)}`)}
  if(t===2){let p,q;do{p=nz(r,-9,9);q=nz(r,-9,9)}while(p===q||p===-q);return ITEM(poly([1,p+q,p*q]),`${bin(1,Math.max(p,q))}${bin(1,Math.min(p,q))}`,peq(pmul([1,p],[1,q]),[1,p+q,p*q]))}
  if(t===3){const b=nz(r,-10,10);return ITEM(poly([1,2*b,b*b]),`${bin(1,b)}²`)}
  if(t===4){const a=pick(r,[2,3,5]),b=ri(r,1,9);if(gcd(a,b)!==1)return ITEM(poly([a*a,0,-1]),`${bin(a,1)}${bin(a,-1)}`);return ITEM(poly([a*a,0,-b*b]),`${bin(a,b)}${bin(a,-b)}`)}
  if(t===5){let a=pick(r,[2,3]),p=nz(r,-7,7),q=nz(r,-7,7);if(gcd(a,p)!==1)p=1;const c=pmul([a,p],[1,q]);return ITEM(poly(c),`${bin(a,p)}${bin(1,q)}`,peq(c,pmul([a,p],[1,q])))}
  const g=ri(r,2,5),b=ri(r,1,6);return ITEM(poly([g,0,-g*b*b]),`${g}${bin(1,b)}${bin(1,-b)}`)}};
const peq=(a,b)=>a.length===b.length&&a.every((x,i)=>x===b[i]);
J.factorprob={fam:'j_alg',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,L==='F'?0:2);
  if(t===0){const p=ri(r,1,8),q=ri(r,p+1,12);return ITEM(`The area of a rectangle is ${poly([1,p+q,p*q])} square units. Its width is (x + ${p}). What is its length?`,`(x + ${q}) units, since ${poly([1,p+q,p*q])} = (x + ${p})(x + ${q})`)}
  if(t===1){const a=ri(r,20,99);const b=pick(r,[1,2,3,5]);return ITEM(`Use a special product to compute ${a+b} × ${a-b} mentally.`,`(${a} + ${b})(${a} ${MN} ${b}) = ${a}² ${MN} ${b}² = ${fmt(a*a)} ${MN} ${b*b} = ${fmt(a*a-b*b)}`)}
  const s=ri(r,4,12);return ITEM(`A square lot has side (x + ${s}) meters. Write its area as a polynomial. Then find the area when x = 3.`,`${poly([1,2*s,s*s])} sq. m; when x = 3: ${(3+s)**2} sq. m`)}};
/* rational algebraic expressions */
const fx=(a,b)=>bin(1,b).replace(/^\(|\)$/g,'')&&bin(1,b);
J.ratsimp={fam:'j_alg',instr:'Simplify. State the values of x that are not allowed.',work:true,g:(r,L)=>{let p,q,s;do{p=nz(r,-7,7);q=nz(r,-7,7);s=nz(r,-7,7)}while(p===q||p===s||q===s);
  if(L==='F'){return ITEM(`(${poly([1,0,-p*p])}) / ${bin(1,p)}`,`${lin(1,-p)}, x ≠ ${sn(-p)}`)}
  if(L==='C')return ITEM(`(${poly([1,p+q,p*q])}) / ${bin(1,p)}`,`${lin(1,q)}, x ≠ ${sn(-p)}`);
  return ITEM(`(${poly([1,p+q,p*q])}) / (${poly([1,p+s,p*s])})`,`${bin(1,q)}/${bin(1,s)}, x ≠ ${[-p,-s].sort((a,b)=>a-b).map(sn).join(', ')}`)}};
J.ratops2={fam:'j_alg',instr:'Perform the operation and simplify.',work:true,g:(r,L)=>{const p=nz(r,-6,6),q=nz(r,-6,6),k=nz(r,-9,9);const t=L==='F'?0:L==='C'?ri(r,0,1):ri(r,1,2);
  if(t===0){const a=ri(r,1,9);return ITEM(`x/${bin(1,p)} + ${a}/${bin(1,p)}`,`${bin(1,a)}/${bin(1,p)}`)}
  if(t===1){if(p===q)return J.ratops2.g(r,L);return ITEM(`(${poly([1,0,-p*p])})/${bin(1,q)} · ${bin(1,q)}/${bin(1,-p)}`,`${lin(1,p)}`)}
  let a=ri(r,1,5),b=ri(r,1,5);if(p===0)return J.ratops2.g(r,L);/* a/x + b/(x+p) = ((a+b)x + ap)/(x(x+p)) */const n=[a+b,a*p];const g=gcd(n[0],n[1]);return ITEM(`${a}/x + ${b}/${bin(1,p)}`,`${g>1?g+'('+poly(n.map(z=>z/g))+')':'('+poly(n)+')'}/[x${bin(1,p)}]`)}};
J.rateq={fam:'j_alg',instr:'Solve by cross-multiplication. Check your answer.',work:true,g:(r,L)=>{for(let k=0;k<200;k++){const m=ri(r,1,9),n=ri(r,1,9);if(m===n||gcd(m,n)!==1)continue;const p=ri(r,-9,9),q=ri(r,-9,9);if(L==='F'){const x=ri(r,-10,20);const b=pick(r,[2,3,4,5]);/* (x + p)/b = (x+p)/b*/const c=x+p;if(c%b)continue;return ITEM(`${bin(1,p)}/${b} = ${sn(c/b)}`.replace('(x)','x'),`x = ${sn(x)}`)}
  const num=m*q-n*p,den=n-m;if(num%den)continue;const x=num/den;if(x+q===0||x+p===0)continue;if(Math.abs(x)>30)continue;return ITEM(`${bin(1,p)}/${bin(1,q)} = ${n===1?m:m+'/'+n}`.replace(/\(x\)/g,'x'),`x = ${sn(x)}`,n*(x+p)===m*(x+q))}return ITEM('(x + 1)/(x + 3) = 2/3','x = 3')}};
J.seq={fam:'j_alg',instr:'Find the pattern.',g:(r,L)=>{const ar=L==='F'||r()<.6;if(ar){const a=ri(r,-10,20),d=nz(r,-7,9);const t=[0,1,2,3].map(i=>a+i*d);if(L==='F')return ITEM(`Find the next two terms: ${t.map(sn).join(', ')}, …`,`${sn(a+4*d)}, ${sn(a+5*d)} (add ${sn(d)} each time)`);const n=ri(r,12,40);return ITEM(`Write the rule for the nth term of ${t.map(sn).join(', ')}, … Then find term ${n}.`,`aₙ = ${poly([d,a-d],'n')}; a${n.toString().split('').map(c=>'₀₁₂₃₄₅₆₇₈₉'[c]).join('')} = ${sn(a+(n-1)*d)}`)}
  const a=pick(r,[1,2,3,5]),q=pick(r,[2,3,-2]);const t=[0,1,2,3].map(i=>a*q**i);const pw=q<0?`(${sn(q)})ⁿ⁻¹`:`${q}ⁿ⁻¹`;return ITEM(`Find the next two terms and the rule: ${t.map(sn).join(', ')}, …`,`${sn(a*q**4)}, ${sn(a*q**5)} (multiply by ${sn(q)}); aₙ = ${a===1?pw:a+(q<0?pw:'('+q+')ⁿ⁻¹')}`)}};
/* ---------- G8 linear ---------- */
J.lineq={fam:'j_alg',instr:'Solve each equation.',work:true,g:(r,L)=>{const x=nz(r,-12,12),a=nz(r,-8,8),b=ri(r,-15,15),c=nz(r,-8,8);const t=L==='F'?ri(r,0,1):L==='C'?ri(r,1,2):ri(r,2,3);let s,ok=true;
  if(t===0)s=`${lin(a,b)} = ${sn(a*x+b)}`;else if(t===1){if(a===c)return J.lineq.g(r,L);const d=a*x+b-c*x;s=`${lin(a,b)} = ${lin(c,d)}`}else if(t===2){const k=ri(r,2,5);s=`${k}${bin(1,b)} = ${sn(k*(x+b))}`.replace('(x)','x')}else{const d=pick(r,[2,3,4,5]);const X=x*d;const e=ri(r,-9,9);s=`x/${d} ${e<0?MN:'+'} ${Math.abs(e)} = ${sn(X/d+e)}`;return ITEM(s,`x = ${sn(X)}`)}
  return ITEM(s,`x = ${sn(x)}`)}};
J.lineqprob={fam:'j_alg',instr:'Write an equation and solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,3);
  if(t===0){const n=ri(r,5,40),d=ri(r,2,15);return ITEM(`The sum of two numbers is ${2*n+d}. One number is ${d} more than the other. Find the numbers.`,`x + (x + ${d}) = ${2*n+d}; x = ${n}; the numbers are ${n} and ${n+d}`)}
  if(t===1){const w=ri(r,3,20),k=ri(r,2,10);return ITEM(`A rectangle's length is ${k} m more than its width. Its perimeter is ${2*(2*w+k)} m. Find its dimensions.`,`2w + 2(w + ${k}) = ${2*(2*w+k)}; width ${w} m, length ${w+k} m`)}
  if(t===2){const p=pick(r,[15,20,25]),q=pick(r,[5,10]),n=ri(r,4,15);const tot=n*(p+q);const who=nm(r);return ITEM(`${who} bought the same number of notebooks at ₱${p} and pens at ₱${q}. ${who} paid ₱${tot} in all. How many of each did she buy?`,`${p}x + ${q}x = ${tot}; x = ${n}`)}
  const a=ri(r,8,15),y=ri(r,2,8);return ITEM(`A mother is ${a*3} years old and her son is ${a} years old. In how many years will the mother be twice as old as her son?`,`${a*3} + x = 2(${a} + x); x = ${a}`)}};
function ineqS(rel,k,v='x'){return`${v} ${rel} ${sn(k)}`}
const FLIP={'<':'>','>':'<','≤':'≥','≥':'≤'};
function intervalS(rel,k){return{'<':`(${MN}∞, ${sn(k)})`,'≤':`(${MN}∞, ${sn(k)}]`,'>':`(${sn(k)}, ∞)`,'≥':`[${sn(k)}, ∞)`}[rel]}
J.linineq={fam:'j_alg',instr:'Solve each inequality. Write the solution set.',work:true,g:(r,L)=>{const x=ri(r,-10,10);const a=L==='F'?ri(r,1,8):nz(r,-6,6),b=ri(r,-12,12);const rel=pick(r,['<','>','≤','≥']);const R=a*x+b;const sol=a<0?FLIP[rel]:rel;
  if(L==='E'){const c=nz(r,-5,5);if(a===c)return J.linineq.g(r,L);const d=R-c*x;const s2=(a-c)<0?FLIP[rel]:rel;return ITEM(`${lin(a,b)} ${rel} ${lin(c,d)}`,`${ineqS(s2,x)}; ${intervalS(s2,x)}`)}
  return ITEM(`${lin(a,b)} ${rel} ${sn(R)}`,`${ineqS(sol,x)}${L==='C'?'; '+intervalS(sol,x):''}`)}};
J.ineqline={fam:'j_alg',instr:'Describe the graph of each solution on a number line.',g:(r,L)=>{const k=ri(r,-8,8);const rel=pick(r,['<','>','≤','≥']);if(L!=='F'&&r()<.5){const a=nz(r,-4,4),x=k,b=ri(r,-9,9);const sol=a<0?FLIP[rel]:rel;return ITEM(`Solve ${lin(a,b)} ${rel} ${sn(a*x+b)} and describe its graph.`,`${ineqS(sol,x)}; ${'≤≥'.includes(sol)?'closed (shaded) dot':'open dot'} at ${sn(x)}, shade to the ${'<≤'.includes(sol)?'left':'right'}`)}
  return ITEM(`x ${rel} ${sn(k)}`,`${'≤≥'.includes(rel)?'closed (shaded) dot':'open dot'} at ${sn(k)}, shade to the ${'<≤'.includes(rel)?'left':'right'}`)}};
J.ineqprob={fam:'j_alg',instr:'Write an inequality and solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,2);
  if(t===0){const b=pick(r,[500,800,1000,1500]),p=pick(r,[35,45,60,75,120]);const mx=Math.floor(b/p);const who=nm(r);return ITEM(`${who} has ₱${b}. A notebook costs ₱${p}. At most how many notebooks can ${who} buy?`,`${p}x ≤ ${b}; x ≤ ${r2(b/p)}; at most ${mx}`)}
  if(t===1){const s=[ri(r,75,90),ri(r,75,90),ri(r,75,90)];const goal=pick(r,[85,88,90]);const need=4*goal-s.reduce((a,b)=>a+b,0);return ITEM(`Your scores are ${s.join(', ')}. What score on the 4th quiz gives an average of at least ${goal}?`,`(${s.join(' + ')} + x)/4 ≥ ${goal}; x ≥ ${need}${need>100?' (not possible if the highest score is 100)':''}`)}
  const f=pick(r,[40,50]),k=pick(r,[10,12,15]),bud=pick(r,[200,250,300]);const mx=Math.floor((bud-f)/k);return ITEM(`A tricycle charges ₱${f} plus ₱${k} per kilometer. You can spend at most ₱${bud}. How many kilometers can you ride?`,`${f} + ${k}x ≤ ${bud}; x ≤ ${r2((bud-f)/k)}; at most ${mx} km (whole kilometers)`)}};
J.lin2sol={fam:'j_alg',instr:'Answer each item.',g:(r,L)=>{const a=nz(r,-5,5),b=nz(r,-5,5),x=ri(r,-6,6),y=ri(r,-6,6);const c=a*x+b*y;const e=`${mono(a,{x:1})}${b<0?' '+MN+' ':' + '}${mono(Math.abs(b),{y:1})} = ${sn(c)}`;const t=ri(r,0,2);
  if(t===0){const ok=r()<.5;const yy=ok?y:y+nz(r,-2,2);return ITEM(`Is (${sn(x)}, ${sn(yy)}) a solution of ${e}?`,ok?`Yes: the left side is ${sn(a*x+b*yy)}, which equals ${sn(c)}`:`No: the left side is ${sn(a*x+b*yy)}, not ${sn(c)}`)}
  if(t===1){const m=nz(r,-4,4),k=ri(r,-8,8),xx=ri(r,-5,5);return ITEM(`For y = ${lin(m,k)}, find y when x = ${sn(xx)}. Write the ordered pair.`,`(${sn(xx)}, ${sn(m*xx+k)})`)}
  const m=nz(r,-3,3),k=ri(r,-5,5);return ITEM(`Give three ordered pairs that are solutions of y = ${lin(m,k)}.`,`Examples: (0, ${sn(k)}), (1, ${sn(m+k)}), (2, ${sn(2*m+k)})`)}};
J.slope={fam:'j_alg',instr:'Find the slope and the intercepts as asked.',work:true,g:(r,L)=>{const t=L==='F'?0:L==='C'?ri(r,0,1):ri(r,1,2);
  if(t===0){let x1=ri(r,-6,6),x2=ri(r,-6,6);if(x1===x2)x2=x1+ri(r,1,5);const y1=ri(r,-6,6),y2=ri(r,-6,6);return ITEM(`Find the slope of the line through (${sn(x1)}, ${sn(y1)}) and (${sn(x2)}, ${sn(y2)}).`,`m = (${sn(y2)} ${MN} ${pn(y1)}) / (${sn(x2)} ${MN} ${pn(x1)}) = ${fr2(y2-y1,x2-x1)}`)}
  if(t===1){const m=nz(r,-6,6),b=ri(r,-9,9);return ITEM(`Give the slope and y-intercept of y = ${lin(m,b)}.`,`slope ${sn(m)}; y-intercept ${sn(b)}, or (0, ${sn(b)})`)}
  let a=nz(r,-6,6),b=nz(r,-6,6);const X=nz(r,-4,4),Y=nz(r,-4,4);/* ax+by=c with intercepts */const c=a*X;if(c%b)return J.slope.g(r,L);const Yi=c/b;return ITEM(`Find the x- and y-intercepts and the slope of ${mono(a,{x:1})}${b<0?' '+MN+' ':' + '}${mono(Math.abs(b),{y:1})} = ${sn(c)}.`,`x-intercept (${sn(c/a)}, 0); y-intercept (0, ${sn(Yi)}); slope ${fr2(-a,b)}`)}};
J.lineeq={fam:'j_alg',instr:'Find the equation of the line. Write it in the form y = mx + b.',work:true,g:(r,L)=>{const m=nz(r,-5,5),b=ri(r,-9,9);const t=L==='F'?0:L==='C'?ri(r,0,2):ri(r,1,3);
  if(t===0)return ITEM(`slope ${sn(m)}, y-intercept ${sn(b)}`,`y = ${lin(m,b)}`);if(t===1){const x=ri(r,-5,5);return ITEM(`slope ${sn(m)}, passing through (${sn(x)}, ${sn(m*x+b)})`,`y = ${lin(m,b)}`)}
  if(t===2){let x1=ri(r,-5,5),x2=ri(r,-5,5);if(x1===x2)x2+=2;return ITEM(`passing through (${sn(x1)}, ${sn(m*x1+b)}) and (${sn(x2)}, ${sn(m*x2+b)})`,`y = ${lin(m,b)}`)}
  const xi=nz(r,-6,6);const yi=-m*xi;/* y = m x - m xi */if(yi===0)return J.lineeq.g(r,L);return ITEM(`x-intercept ${sn(xi)} and y-intercept ${sn(yi)}`,`y = ${lin(m,yi)}`)}};
J.sketchline={fam:'j_alg',instr:'Give two points you would plot to sketch each line. Then describe the line.',g:(r,L)=>{const m=nz(r,-4,4),b=ri(r,-6,6);const t=ri(r,0,2);if(t===0)return ITEM(`y = ${lin(m,b)}`,`(0, ${sn(b)}) and (1, ${sn(m+b)}); the line ${m>0?'rises':'falls'} from left to right`);
  if(t===1){const a=nz(r,-5,5),bb=nz(r,-5,5);const k=a*bb*ri(r,1,2);return ITEM(`${mono(a,{x:1})}${bb<0?' '+MN+' ':' + '}${mono(Math.abs(bb),{y:1})} = ${sn(k)} (use the intercepts)`,`(${sn(k/a)}, 0) and (0, ${sn(k/bb)})`)}
  const x=ri(r,-3,3);return ITEM(`slope ${sn(m)} through (${sn(x)}, ${sn(m*x+b)})`,`Plot (${sn(x)}, ${sn(m*x+b)}); move 1 right and ${Math.abs(m)} ${m>0?'up':'down'} to (${sn(x+1)}, ${sn(m*x+m+b)})`)}};
/* systems */
function sysEq(a,b,c){return`${mono(a,{x:1})}${b<0?' '+MN+' ':' + '}${mono(Math.abs(b),{y:1})} = ${sn(c)}`}
function mkSys(r,L){for(let k=0;k<200;k++){const x=ri(r,-6,6),y=ri(r,-6,6);const a=nz(r,-4,4),b=L==='F'?1:nz(r,-4,4),c=nz(r,-4,4),d=nz(r,-4,4);if(a*d-b*c===0)continue;return{x,y,e1:[a,b,a*x+b*y],e2:[c,d,c*x+d*y]}}}
J.sysdef={fam:'j_alg',instr:'Answer each item.',g:(r,L)=>{const S=mkSys(r,L);const ok=r()<.5;const X=S.x,Y=ok?S.y:S.y+1;const v=S.e1[0]*X+S.e1[1]*Y===S.e1[2]&&S.e2[0]*X+S.e2[1]*Y===S.e2[2];return ITEM(`Is (${sn(X)}, ${sn(Y)}) a solution of the system ${sysEq(...S.e1)} and ${sysEq(...S.e2)}?`,v?'Yes, it makes both equations true.':'No, it does not make both equations true.')}};
J.syssolve={fam:'j_alg',instr:'Solve each system.',work:true,g:(r,L)=>{const S=mkSys(r,L);return ITEM(`${sysEq(...S.e1)}\n${sysEq(...S.e2)}`.replace('\n','  and  '),`(${sn(S.x)}, ${sn(S.y)})`)}};
J.sysgraph={fam:'j_alg',instr:'Solve by graphing. Write the point where the lines meet.',g:(r,L)=>{const x=ri(r,-4,4),y=ri(r,-4,4);let m1=nz(r,-3,3),m2=nz(r,-3,3);if(m1===m2)m2=-m1;return ITEM(`y = ${lin(m1,y-m1*x)} and y = ${lin(m2,y-m2*x)}`,`(${sn(x)}, ${sn(y)})`)}};
J.sysclass={fam:'j_alg',instr:'Tell whether each system has one solution, no solution, or infinitely many solutions.',g:(r,L)=>{const m=nz(r,-4,4),b=ri(r,-6,6);const t=ri(r,0,2);let m2=m,b2=b,k=ri(r,2,3);if(t===0){m2=m+nz(r,-2,2)||m+1}else if(t===1){b2=b+nz(r,-5,5)}
  const e2=t===2?`${k}y = ${lin(k*m,k*b)}`:`y = ${lin(m2,b2)}`;return ITEM(`y = ${lin(m,b)} and ${e2}`,['one solution (different slopes; the lines intersect)','no solution (same slope, different y-intercepts; the lines are parallel)','infinitely many solutions (the equations describe the same line)'][t])}};
J.sysprob={fam:'j_alg',instr:'Write a system of equations and solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,2);
  if(t===0){const a=ri(r,10,40),b=ri(r,5,a-1);return ITEM(`The sum of two numbers is ${a+b} and their difference is ${a-b}. Find the numbers.`,`x + y = ${a+b}, x − y = ${a-b}; ${a} and ${b}`)}
  if(t===1){const pa=pick(r,[15,20,25]),pc=pick(r,[8,10,12]),na=ri(r,20,80),nc=ri(r,20,80);return ITEM(`Tickets for a school play cost ₱${pa} for adults and ₱${pc} for children. ${na+nc} tickets were sold for ₱${fmt(pa*na+pc*nc)}. How many of each were sold?`,`a + c = ${na+nc}, ${pa}a + ${pc}c = ${pa*na+pc*nc}; ${na} adult, ${nc} child tickets`)}
  const x=pick(r,[12,15,18,20,25]),y=pick(r,[30,35,40,45,55]);const a=ri(r,2,4),b=ri(r,1,3),c=ri(r,1,3),d=ri(r,2,4);if(a*d-b*c===0)return J.sysprob.g(r,L);return ITEM(`${a} kg of sugar and ${b} kg of flour cost ₱${a*x+b*y}. ${c} kg of sugar and ${d} kg of flour cost ₱${c*x+d*y}. Find the price per kg of each.`,`sugar ₱${x}/kg, flour ₱${y}/kg`)}};
J.ineq2={fam:'j_alg',instr:'Answer each item.',g:(r,L)=>{const m=nz(r,-3,3),b=ri(r,-5,5),rel=pick(r,['<','>','≤','≥']);const x=ri(r,-4,4),y=ri(r,-8,8);const val=m*x+b;const ok={'<':y<val,'>':y>val,'≤':y<=val,'≥':y>=val}[rel];
  if(L==='E'){const c=pick(r,[200,300,500]),p=pick(r,[20,25]),q=pick(r,[40,50]);const A=ri(r,2,8),B=ri(r,2,5);const tot=p*A+q*B;return ITEM(`Juice costs ₱${p} and sandwiches cost ₱${q}. You have ₱${c}. Write an inequality for x juices and y sandwiches. Can you buy ${A} juices and ${B} sandwiches?`,`${p}x + ${q}y ≤ ${c}; ${tot<=c?'yes':'no'} (${p}(${A}) + ${q}(${B}) = ${tot})`)}
  return ITEM(`Is (${sn(x)}, ${sn(y)}) a solution of y ${rel} ${lin(m,b)}?`,`${ok?'Yes':'No'}: ${sn(y)} ${rel} ${sn(val)} is ${ok?'true':'false'}`)}};
/* ---------- G9 functions ---------- */
J.isfunc={fam:'j_func',instr:'Tell whether each relation is a function. Explain.',g:(r,L)=>{const n=4;const xs=shuf(r,[-3,-2,-1,0,1,2,3,4]).slice(0,n);const f=r()<.5;const pts=xs.map(x=>[x,ri(r,-5,5)]);if(!f)pts[3]=[pts[0][0],pts[0][1]+ri(r,1,3)];
  if(L==='E'&&r()<.5){const X=[['y = 2x + 1','function'],['y = x²','function'],['x = y²','not a function (for x = 4, y = 2 or y = −2)'],['y² + x² = 25','not a function (for x = 0, y = 5 or y = −5)'],['y = |x|','function'],['x = 3','not a function (a vertical line)']];const z=pick(r,X);return ITEM(`Is ${z[0]} a function?`,z[1])}
  return ITEM(`{${pts.map(p=>`(${sn(p[0])}, ${sn(p[1])})`).join(', ')}}`,f?'function (each x has only one y)':`not a function (x = ${sn(pts[0][0])} has two y-values)`)}};
J.domrange={fam:'j_func',instr:'Give the domain and range.',g:(r,L)=>{const t=L==='F'?0:L==='C'?ri(r,0,1):ri(r,1,3);const S=a=>'{'+[...new Set(a)].sort((x,y)=>x-y).map(sn).join(', ')+'}';
  if(t===0){const xs=shuf(r,[-3,-2,-1,0,1,2,3,4,5]).slice(0,4);const pts=xs.map(x=>[x,ri(r,-4,6)]);return ITEM(`{${pts.map(p=>`(${sn(p[0])}, ${sn(p[1])})`).join(', ')}}`,`domain ${S(pts.map(p=>p[0]))}; range ${S(pts.map(p=>p[1]))}`)}
  if(t===1){const m=nz(r,-5,5),b=ri(r,-9,9);return ITEM(`f(x) = ${lin(m,b)}`,'domain: all real numbers; range: all real numbers')}
  if(t===2){const a=ri(r,-6,6);return ITEM(`f(x) = √(${lin(1,-a)})`.replace('(x)','x'),`domain: x ≥ ${sn(a)}; range: y ≥ 0`)}
  const a=nz(r,-6,6);return ITEM(`f(x) = 1/${bin(1,-a)}`,`domain: all real numbers except ${sn(a)}; range: all real numbers except 0`)}};
J.funcexpr={fam:'j_func',instr:'Write a function rule for each table.',g:(r,L)=>{const m=nz(r,-5,6),b=ri(r,-9,9);const x0=ri(r,-2,1);const xs=[0,1,2,3].map(i=>x0+i);return ITEM(`x: ${xs.map(sn).join(', ')}  |  y: ${xs.map(x=>sn(m*x+b)).join(', ')}`,`f(x) = ${lin(m,b)}`)}};
J.slopezero={fam:'j_func',instr:'Find the slope (rate of change) and the zero of each linear function.',work:true,g:(r,L)=>{const m=nz(r,-6,6),b=ri(r,-12,12);const t=L==='F'?0:ri(r,0,1);
  if(t===0)return ITEM(`f(x) = ${lin(m,b)}`,`slope ${sn(m)}; zero x = ${fr2(-b,m)}`);const st=pick(r,[1,2]);const xs=[0,1,2,3].map(i=>i*st);return ITEM(`x: ${xs.join(', ')}  |  f(x): ${xs.map(x=>sn(m*x+b)).join(', ')}`,`slope ${sn(m)}; f(x) = ${lin(m,b)}; zero x = ${fr2(-b,m)}`)}};
J.linfunc={fam:'j_func',instr:'For each function, give the domain, range, intercepts and slope.',work:true,g:(r,L)=>{const m=nz(r,-5,5),b=nz(r,-10,10);return ITEM(`f(x) = ${lin(m,b)}`,`domain and range: all real numbers; x-intercept (${fr2(-b,m)}, 0); y-intercept (0, ${sn(b)}); slope ${sn(m)}`)}};
J.linreal={fam:'j_func',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const f=pick(r,[20,30,40,50]),k=pick(r,[8,10,12,15]);const x=ri(r,2,12);const t=L==='F'?0:ri(r,0,2);const veh=pick(r,['A tricycle','A delivery service','An internet café']);const unit=veh==='An internet café'?'hour':'kilometer';
  if(t===0)return ITEM(`${veh} charges ₱${f} plus ₱${k} per ${unit}. Write the cost C as a function of x ${unit}s.`,`C(x) = ${k}x + ${f}`);if(t===1)return ITEM(`${veh} charges ₱${f} plus ₱${k} per ${unit}. How much is the cost for ${x} ${unit}s?`,`C(${x}) = ${k}(${x}) + ${f} = ₱${k*x+f}`);return ITEM(`${veh} charges ₱${f} plus ₱${k} per ${unit}. A customer paid ₱${k*x+f}. How many ${unit}s?`,`${k}x + ${f} = ${k*x+f}; x = ${x}`)}};
J.parperp={fam:'j_func',instr:'Tell whether the lines are parallel, perpendicular, or neither.',g:(r,L)=>{const m=pick(r,[qn(1,1),qn(2,1),qn(3,1),qn(-1,1),qn(-2,1),qn(-3,1),qn(1,2),qn(-2,3),qn(3,4)]);const perp=qn(-m.d,m.n);
  if(L==='E'&&r()<.5){const b=ri(r,-5,5);const mx=m.d===1?(m.n===1?'':m.n===-1?MN:sn(m.n)):'('+qs(m)+')';return ITEM(`Give the slope of a line perpendicular to y = ${mx}x${b?(b>0?' + '+b:' '+MN+' '+(-b)):''}. Then give the slope of a line parallel to it.`,`perpendicular: ${qs(perp)}; parallel: ${qs(m)}`)}
  const t=ri(r,0,2);const m2=t===0?m:t===1?perp:qadd(m,qn(1,1));return ITEM(`line 1 has slope ${qs(m)}; line 2 has slope ${qs(m2)}`,['parallel (equal slopes)','perpendicular (the slopes are negative reciprocals; their product is −1)','neither'][t])}};
/* quadratics */
const vform=(a,h,k)=>`y = ${a===1?'':a===-1?MN:sn(a)}${h===0?'x':'(x '+(h>0?MN+' '+h:'+ '+(-h))+')'}²${k?(k>0?' + '+k:' '+MN+' '+(-k)):''}`;
J.quadreal={fam:'j_func',instr:'Write a quadratic expression or equation for each situation.',g:(r,L)=>{const k=ri(r,2,8),P=pick(r,[20,24,30,36,40]);const X=[[`A rectangular garden is x m wide and ${k} m longer than it is wide. Write its area A.`,`A = x(x + ${k}) = x² + ${k}x`],[`A rectangle has a perimeter of ${P} m. One side is x m. Write its area A in terms of x.`,`A = x(${P/2} − x) = ${P/2}x − x²`],[`The product of two consecutive integers is P. Write P in terms of the smaller integer n.`,`P = n(n + 1) = n² + n`],[`A square picture with side x cm has a ${k}-cm border all around. Write the total area.`,`A = (x + ${2*k})²`],[`A ball is thrown up. Its height is h = ${pick(r,[20,25,30])}t − 5t². What kind of relationship is this? Why?`,'quadratic, because the highest power of t is 2']];return ITEM(...pick(r,X))}};
J.quadtable={fam:'j_func',instr:'Complete the table of values. Then plot the points to graph.',g:(r,L)=>{const a=pick(r,L==='F'?[1,-1,2]:[1,-1,2,-2,0.5]),t=L==='F'?ri(r,0,1):ri(r,0,2),b=nz(r,-4,4);const xs=[-2,-1,0,1,2];const f=x=>t===0?a*x*x:t===1?a*x*x+b:a*(x-b)**2;const ca=a===1?'':a===-1?MN:a===0.5?'(1/2)':sn(a);const name=t===0?`y = ${ca}x²`:t===1?`y = ${ca}x²${b>0?' + '+b:' '+MN+' '+(-b)}`:vform(a,b,0).replace('0.5(','(1/2)(');
  const xs2=t===2?xs.map(x=>x+b):xs;return ITEM(`${name}; x = ${xs2.map(sn).join(', ')}`,`y = ${xs2.map(x=>dn(f(x))).map(s=>s.replace('-',MN)).join(', ')}`)}};
J.parabola={fam:'j_func',instr:'Give the features of each parabola.',work:true,g:(r,L)=>{const a=pick(r,[1,-1,2,-2,3]),h=ri(r,-5,5);let k=ri(r,-9,9);let ints='';if(L==='E'){const m=ri(r,1,4);k=-a*m*m;ints=`; x-intercepts ${sn(h-m)} and ${sn(h+m)}`}
  return ITEM(vform(a,h,k),`vertex (${sn(h)}, ${sn(k)}); axis of symmetry x = ${sn(h)}; opens ${a>0?'upward':'downward'}; ${a>0?'minimum':'maximum'} value ${sn(k)}${L!=='F'?`; ${a>0?'decreasing':'increasing'} for x < ${sn(h)}, ${a>0?'increasing':'decreasing'} for x > ${sn(h)}`:''}${ints}`)}};
J.vertexform={fam:'j_func',instr:'Write in the form y = a(x − h)² + k by completing the square.',work:true,g:(r,L)=>{const a=pick(r,L==='F'?[1]:L==='C'?[1,-1]:[2,-2,3,-1]),h=nz(r,-6,6),k=ri(r,-12,12);const b=-2*a*h,c=a*h*h+k;if(L==='E'&&r()<.4)return ITEM(`Write ${vform(a,h,k)} in the form y = ax² + bx + c.`,`y = ${poly([a,b,c])}`);return ITEM(`y = ${poly([a,b,c])}`,vform(a,h,k))}};
J.paramfx={fam:'j_func',instr:'Compare each graph with the graph of y = x².',g:(r,L)=>{const t=ri(r,0,4);const a=pick(r,[2,3,4]),k=ri(r,1,8),h=ri(r,1,6);const X=[[`y = ${a}x²`,'narrower (stretched); same vertex (0, 0); opens upward'],[`y = (1/${a})x²`,'wider; same vertex (0, 0); opens upward'],[`y = ${MN}x²`,'same shape, reflected over the x-axis (opens downward)'],[`y = x² + ${k}`,`shifted ${k} unit${k>1?'s':''} up; vertex (0, ${k})`],[`y = (x ${MN} ${h})²`,`shifted ${h} unit${h>1?'s':''} to the right; vertex (${h}, 0)`]];if(L==='E'){return ITEM(`y = ${MN}${a}(x + ${h})² + ${k}`,`opens downward, narrower, shifted ${h} unit${h>1?'s':''} left and ${k} unit${k>1?'s':''} up; vertex (${MN}${h}, ${k}); maximum value ${k}`)}return ITEM(...X[t])}};
J.qzeros={fam:'j_func',instr:'Find the zeros of each quadratic function.',work:true,g:(r,L)=>{let p=ri(r,-8,8),q=ri(r,-8,8);if(p===q)q=p+ri(r,1,4);const a=L==='E'?pick(r,[1,2,-1]):1;const zs=[p,q].sort((x,y)=>x-y).map(sn).join(' and ');
  if(L==='F')return ITEM(`f(x) = ${p===0?'x':bin(1,-p)}${q===0?'x':bin(1,-q)}`,`x = ${zs}`);return ITEM(`f(x) = ${poly(pmul([a],pmul([1,-p],[1,-q])))}`,`x = ${zs}`,peval(pmul([a],pmul([1,-p],[1,-q])),p)===0&&peval(pmul([a],pmul([1,-p],[1,-q])),q)===0)}};
function qform(a,b,c){/* returns string of roots */const D=b*b-4*a*c;if(D<0)return'no real roots';if(isSq(D)){const s=Math.sqrt(D);const x1=qn(-b+s,2*a),x2=qn(-b-s,2*a);return D===0?`x = ${qs(x1)}`:`x = ${[x1,x2].sort((u,v)=>u.n/u.d-v.n/v.d).map(qs).join(' or x = ')}`}
  /* simplify √D = k√m */let k=1,m=D,i=2;while(i*i<=m){while(m%(i*i)===0){m/=i*i;k*=i}i++}let p=-b,q=k,d=2*a;if(d<0){p=-p;d=-d}const g=gcd(gcd(Math.abs(p),q),d);p/=g;q/=g;d/=g;const rt=(q===1?'':q)+'√'+m;if(!p)return d===1?`x = ±${rt}`:`x = ±${rt}/${d}`;const top=sn(p)+' ± '+rt;return d===1?`x = ${top}`:`x = (${top})/${d}`}
J.qsolve={fam:'j_func',instr:'Solve each quadratic equation. Use the method asked.',work:true,g:(r,L)=>{const t=L==='F'?ri(r,0,1):L==='C'?ri(r,1,2):pick(r,[2,3]);
  if(t===0){const a=pick(r,[1,2,3]),s=ri(r,1,9);const c=a*s*s;return ITEM(`Extracting square roots: ${a===1?'':a}x² ${MN} ${c} = 0`,`x = ±${s}`)}
  if(t===1){let p=nz(r,-9,9),q=ri(r,-9,9);if(p===q)q++;const c=[1,-(p+q),p*q];return ITEM(`Factoring: ${poly(c)} = 0`,`x = ${[p,q].sort((x,y)=>x-y).map(sn).join(' or x = ')}`,peval(c,p)===0&&peval(c,q)===0)}
  for(let k=0;k<200;k++){const a=pick(r,[1,1,2,3]),b=ri(r,-9,9),c=ri(r,-9,9);const D=b*b-4*a*c;if(D<=0||c===0)continue;if(t===2&&!isSq(D)&&r()<.5)continue;return ITEM(`Quadratic formula: ${poly([a,b,c])} = 0`,qform(a,b,c))}return ITEM('Quadratic formula: x² − 5x + 6 = 0','x = 2 or x = 3')}};
J.qprob={fam:'j_func',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,2);
  if(t===0){const w=ri(r,3,15),k=ri(r,2,8);return ITEM(`A rectangular lot is ${k} m longer than it is wide. Its area is ${w*(w+k)} sq. m. Find its dimensions.`,`x(x + ${k}) = ${w*(w+k)}; width ${w} m, length ${w+k} m (reject the negative root)`)}
  if(t===1){const n=ri(r,3,20);return ITEM(`The product of two consecutive positive integers is ${n*(n+1)}. Find the integers.`,`n(n + 1) = ${n*(n+1)}; ${n} and ${n+1}`)}
  const T=ri(r,2,6);const v=10*T/2*2;/* h=vt-5t^2 lands when t=v/5 */const vv=5*T;return ITEM(`A ball is thrown upward. Its height is h = ${vv}t − 5t² meters after t seconds. When does it hit the ground? What is its greatest height?`,`${vv}t − 5t² = 0, t = ${T} s; greatest height at t = ${dn(T/2)} s: h = ${dn(vv*T/2-5*T*T/4)} m`)}};
/* variation */
J.vartype={fam:'j_func',instr:'Tell whether each situation shows direct variation or inverse variation.',g:(r,L)=>{const X=[['the cost of rice and the number of kilos bought','direct'],['the number of workers and the days needed to finish a job','inverse'],['the distance traveled and the time, at the same speed','direct'],['the speed of a jeepney and the time to travel a fixed route','inverse'],['the number of pages printed and the ink used','direct'],['the number of people sharing a pizza and the size of each share','inverse'],['the pay of a worker and the hours worked at the same hourly rate','direct'],['the number of faucets filling a tank and the time to fill it','inverse']];const z=pick(r,X);if(L==='E'){const k=pick(r,[12,24,36]);const st=pick(r,[1,2]);const xs=[1,2,3,4].map(i=>i*st);const inv=r()<.5;return ITEM(`x: ${xs.join(', ')}  |  y: ${xs.map(x=>inv?r2(k/x):k*x/xs[0]).join(', ')}. Direct or inverse?`,inv?`inverse (xy = ${k} is constant)`:`direct (y/x = ${k/xs[0]} is constant)`)}return ITEM(cap(z[0])+'.',z[1]+' variation')}};
J.vareq={fam:'j_func',instr:'Write the variation equation.',g:(r,L)=>{const k=pick(r,[2,3,4,5,6,12,18,24]);const inv=L!=='F'&&r()<.5;const xs=inv?[1,2,3,6]:[1,2,3,4];const ys=xs.map(x=>inv?k/x:k*x);return ITEM(`x: ${xs.join(', ')}  |  y: ${ys.map(v=>r2(v)).join(', ')}`,inv?`y = ${k}/x (inverse variation, k = ${k})`:`y = ${k}x (direct variation, k = ${k})`)}};
J.varprob={fam:'j_func',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,L==='E'?3:2);
  if(t===0){const k=pick(r,[3,4,5,6]),x1=ri(r,2,6),x2=ri(r,7,15);return ITEM(`y varies directly as x. y = ${k*x1} when x = ${x1}. Find y when x = ${x2}.`,`k = ${k}; y = ${k*x2}`)}
  if(t===1){const w=pick(r,[4,6,8]),d=pick(r,[6,9,12,15]);const w2=pick(r,[2,3,12].filter(x=>(w*d)%x===0));return ITEM(`${w} workers can finish a classroom repair in ${d} days. How long will ${w2} workers take, at the same rate?`,`${w} × ${d} = ${w*d}; ${w*d} ÷ ${w2} = ${r2(w*d/w2)} days`)}
  if(t===2){const s=pick(r,[40,50,60]),h=pick(r,[2,3,4,6]);const s2=pick(r,[20,25,30,40,60,75,80,100,120].filter(x=>(s*h)%x===0&&x!==s));return ITEM(`A bus at ${s} km/h takes ${h} hours to make a trip. How long does the trip take at ${s2} km/h?`,`${s} × ${h} = ${s*h} km; ${s*h} ÷ ${s2} = ${r2(s*h/s2)} hours`)}
  const k=pick(r,[2,3,4]),x=ri(r,2,5),z=ri(r,2,5);return ITEM(`y varies jointly as x and z. y = ${k*x*z} when x = ${x} and z = ${z}. Find y when x = ${x+1} and z = ${z+1}.`,`k = ${k}; y = ${k*(x+1)*(z+1)}`)}};
/* ---------- G10 ---------- */
function qineqSol(p,q,rel){/* (x-p)(x-q) rel 0, p<q */const c='≤≥'.includes(rel);const lo=sn(p),hi=sn(q);if(rel==='<'||rel==='≤')return{s:`${lo} ${c?'≤':'<'} x ${c?'≤':'<'} ${hi}`,i:`${c?'[':'('}${lo}, ${hi}${c?']':')'}`};return{s:`x ${c?'≤':'<'} ${lo} or x ${c?'≥':'>'} ${hi}`,i:`(${MN}∞, ${lo}${c?']':')'} ∪ ${c?'[':'('}${hi}, ∞)`}}
J.qineqline={fam:'j_alg',instr:'Show the solution of each inequality on a number line. Describe the graph.',g:(r,L)=>{let p=ri(r,-6,5),q=ri(r,p+1,8);const rel=pick(r,['<','>','≤','≥']);const S=qineqSol(p,q,rel);const dot='≤≥'.includes(rel)?'closed dots':'open dots';return ITEM(`${bin(1,-p)}${bin(1,-q)} ${rel} 0`.replace(/\(x\)/g,'x'),`${S.s}; ${dot} at ${sn(p)} and ${sn(q)}, shade ${'<≤'.includes(rel)?'between them':'to the left of '+sn(p)+' and to the right of '+sn(q)}`)}};
J.qineq={fam:'j_alg',instr:'Solve each quadratic inequality. Write the solution in set-builder and interval notation.',work:true,g:(r,L)=>{let p=ri(r,-7,6),q=ri(r,p+1,8);const rel=pick(r,['<','>','≤','≥']);const S=qineqSol(p,q,rel);const c=[1,-(p+q),p*q];if(L==='F'&&p!==-q)return ITEM(`${poly(c)} ${rel} 0`,`${S.s}`);return ITEM(`${poly(c)} ${rel} 0`,`{x | ${S.s}}; ${S.i}`)}};
J.qineqprob={fam:'j_alg',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,1);if(t===0){const t1=ri(r,1,3),t2=ri(r,t1+1,6);const s=t1+t2,p=t1*t2;return ITEM(`A ball's height is h = ${5*s}t − 5t² meters. For what times t is the ball higher than ${5*p} m?`,`${5*s}t − 5t² > ${5*p} → t² − ${s}t + ${p} < 0 → ${t1} < t < ${t2} seconds`)}
  const w=ri(r,4,10),k=ri(r,2,6);return ITEM(`A rectangle is x m wide and (x + ${k}) m long. For what widths is the area at least ${w*(w+k)} sq. m?`,`x(x + ${k}) ≥ ${w*(w+k)} → (x ${MN} ${w})(x + ${w+k}) ≥ 0; since x > 0, x ≥ ${w} m`)}};
J.qineq2={fam:'j_alg',instr:'Tell whether each point is a solution of the inequality.',g:(r,L)=>{const a=pick(r,[1,-1,2]),b=ri(r,-4,4),c=ri(r,-5,5);const x=ri(r,-3,3),y=ri(r,-8,8);const rel=pick(r,['<','>','≤','≥']);const v=a*x*x+b*x+c;const ok={'<':y<v,'>':y>v,'≤':y<=v,'≥':y>=v}[rel];return ITEM(`(${sn(x)}, ${sn(y)}); y ${rel} ${poly([a,b,c])}`,`${ok?'Yes':'No'}: ${sn(y)} ${rel} ${sn(v)} is ${ok?'true':'false'}`)}};
J.region={fam:'j_alg',instr:'Describe the graph of each inequality: boundary line or curve, solid or dashed, and the shaded region.',g:(r,L)=>{const rel=pick(r,['<','>','≤','≥']);const q=L!=='F'&&r()<.5;const m=nz(r,-3,3),b=ri(r,-5,5);const rhs=q?poly([pick(r,[1,-1]),0,b]):lin(m,b);return ITEM(`y ${rel} ${rhs}`,`boundary y = ${rhs} (${q?'parabola':'line'}), ${'≤≥'.includes(rel)?'solid':'dashed'}; shade ${'>≥'.includes(rel)?'above':'below'} it`)}};
J.abseq={fam:'j_alg',instr:'Solve each absolute value equation.',work:true,g:(r,L)=>{if(L!=='F'&&r()<.15){const k=ri(r,1,9);return ITEM(`|x + ${k}| = ${MN}${ri(r,1,9)}`,'no solution (an absolute value cannot be negative)')}for(let k=0;k<100;k++){const a=L==='F'?1:pick(r,[1,2,3]);const x1=ri(r,-8,10),x2=ri(r,-10,8);if(x1<=x2)continue;const d=a*(x1-x2);if(d%2)continue;const c=d/2,b=c-a*x1;return ITEM(`|${lin(a,b)}| = ${c}`,`x = ${sn(x2)} or x = ${sn(x1)}`,Math.abs(a*x1+b)===c&&Math.abs(a*x2+b)===c)}return ITEM('|x − 2| = 5','x = −3 or x = 7')}};
J.absineq={fam:'j_alg',instr:'Solve each absolute value inequality. Write the solution in interval notation.',work:true,g:(r,L)=>{for(let k=0;k<100;k++){const a=L==='F'?1:pick(r,[1,2]);const lo=ri(r,-8,4),hi=ri(r,lo+1,10);if((a*(hi-lo))%2||(a*(lo+hi))%2)continue;const c=a*(hi-lo)/2,b=a*(lo+hi)/2;const rel=pick(r,['<','≤','>','≥']);const cl='≤≥'.includes(rel);
  const ans='<≤'.includes(rel)?`${sn(lo)} ${cl?'≤':'<'} x ${cl?'≤':'<'} ${sn(hi)}; ${cl?'[':'('}${sn(lo)}, ${sn(hi)}${cl?']':')'}`:`x ${cl?'≤':'<'} ${sn(lo)} or x ${cl?'≥':'>'} ${sn(hi)}; (${MN}∞, ${sn(lo)}${cl?']':')'} ∪ ${cl?'[':'('}${sn(hi)}, ∞)`;return ITEM(`|${lin(a,-b)}| ${rel} ${c}`,ans)}return ITEM('|x| < 3','−3 < x < 3; (−3, 3)')}};
J.ratexp={fam:'j_alg',instr:'Simplify or rewrite as asked.',g:(r,L)=>{const t=L==='F'?ri(r,0,1):ri(r,0,3);const B=[[4,2],[8,2],[9,3],[16,2],[27,3],[32,2],[64,2],[81,3],[125,5],[16,4],[64,4],[81,9]];
  if(t===0){const roots={4:[2,2],8:[3,2],9:[2,3],16:[4,2],27:[3,3],32:[5,2],64:[3,4],81:[4,3],125:[3,5]};const n=pick(r,Object.keys(roots).map(Number));const [k,base]=roots[n];return ITEM(`${n}^(1/${k})`,`${base}`)}
  if(t===1){const P=[[8,3,2,4],[27,3,2,9],[16,4,3,8],[32,5,2,4],[4,2,3,8],[9,2,3,27],[64,3,2,16],[125,3,2,25],[81,4,3,27]];const p=pick(r,P);return ITEM(`${p[0]}^(${p[2]}/${p[1]})`,`${p[3]}`)}
  if(t===2){const P=[[4,2,1,'1/2'],[9,2,1,'1/3'],[8,3,1,'1/2'],[16,4,3,'1/8'],[27,3,2,'1/9']];const p=pick(r,P);return ITEM(`${p[0]}^(${MN}${p[2]}/${p[1]})`,p[3])}
  const m=ri(r,2,5),n=ri(r,2,4);if(m===n)return ITEM(`Write x^(${m}/${n+1}) in radical form.`,`${n+1===3?'∛':n+1===4?'∜':(n+1)+'th root of '}(x${sup(m)})`.replace('th root of (','th root of (').replace(/^(\d)th root of/,'$1th root of'));return ITEM(`Write x^(${m}/${n}) in radical form.`,n===2?`√(x${sup(m)})`:n===3?`∛(x${sup(m)})`:`∜(x${sup(m)})`)}};
J.radsimp={fam:'j_alg',instr:'Simplify each radical. Assume variables are positive.',g:(r,L)=>{let n;do{n=pick(r,[2,3,5,6,7])*pick(r,[4,9,16,25,36,49])}while(n>300);const t=L==='F'?0:ri(r,0,2);if(t===0)return ITEM(`√${n}`,rad(1,n));
  if(t===1){const e=pick(r,[2,3,4,5]);const k=Math.floor(e/2),re=e%2;return ITEM(`√(${n}x${sup(e)})`,`${rad(1,n).replace(/√/,'x'+(k>1?sup(k):'')+'√').replace(/^x/,'x')}${re?'x':''}`.replace(/(\d*)x(\S*)√(\d+)x$/,'$1x$2√($3x)'))}
  const c=pick(r,[16,24,54,40,81,250,128,32]);const cub={16:'2∛2',24:'2∛3',54:'3∛2',40:'2∛5',81:'3∛3',250:'5∛2',128:'4∛2',32:'2∛4'}[c];return ITEM(`∛${c}`,cub)}};
J.radops={fam:'j_alg',instr:'Perform the operation. Simplify. Rationalize denominators.',work:true,g:(r,L)=>{const m=pick(r,[2,3,5,6,7]);const t=L==='F'?ri(r,0,1):L==='C'?ri(r,1,3):ri(r,3,4);
  if(t===0){const a=nz(r,-6,9),b=nz(r,-6,9);return ITEM(`${rad(a,m)} + ${rad(b,m)}`.replace('+ −','− '),rad(a+b,m))}
  if(t===1){const s1=pick(r,[1,4,9]),s2=pick(r,[4,9,16,25].filter(x=>x!==s1));const a=ri(r,1,5),b=ri(r,1,5);const tot=a*Math.sqrt(s1)+b*Math.sqrt(s2);return ITEM(`${a===1?'':a}√${s1*m} + ${b===1?'':b}√${s2*m}`,rad(tot,m))}
  if(t===2){const a=pick(r,[2,3,5,6]),b=pick(r,[2,3,6,8,10,12]);return ITEM(`√${a} × √${b}`,rad(1,a*b))}
  if(t===3){const k=ri(r,1,9);const g=gcd(k,m);const num=k/g,den=m/g;return ITEM(`${k}/√${m}`,den===1?rad(num,m):`${num===1?'':num}√${m}/${den}`)}
  /* k/(p - √n) */const p=ri(r,2,5),n=pick(r,[2,3,5,7].filter(x=>x!==p*p));const k=ri(r,1,6);const D=p*p-n;const g=gcd(gcd(k*p,k),Math.abs(D));let A=k*p/g,Bc=k/g,Dd=D/g;if(Dd<0){A=-A;Bc=-Bc;Dd=-Dd}const top=`${sn(A)} ${Bc<0?MN:'+'} ${Math.abs(Bc)===1?'':Math.abs(Bc)}√${n}`;return ITEM(`${k}/(${p} ${MN} √${n})`,Dd===1?top:`(${top})/${Dd}`)}};
J.discrim={fam:'j_alg',instr:'Use the discriminant to describe the roots.',work:true,g:(r,L)=>{const a=pick(r,[1,1,2,3,-1]),b=nz(r,-8,8),c=nz(r,-8,8);const D=b*b-4*a*c;const kind=D>0?(isSq(D)?'two distinct real roots (rational)':'two distinct real roots (irrational)'):D===0?'one real root (a double root)':'no real roots (two non-real roots)';return ITEM(`${poly([a,b,c])} = 0`,`b² − 4ac = ${pn(b)}² − 4(${sn(a)})(${sn(c)}) = ${sn(D)}; ${kind}`)}};
J.qfrom={fam:'j_alg',instr:'Find the equation of the quadratic function. Write it in the form y = ax² + bx + c.',work:true,g:(r,L)=>{const a=pick(r,L==='F'?[1]:[1,-1,2]),p=ri(r,-5,5),q=ri(r,-5,5);const c=pmul([a],pmul([1,-p],[1,-q]));const t=L==='F'?0:ri(r,0,2);
  if(t===0)return ITEM(`zeros ${sn(p)} and ${sn(q)}, and a = ${sn(a)}`,`y = ${poly(c)}`);if(t===1){const x0=ri(r,-3,3);if(x0===p||x0===q)return J.qfrom.g(r,L);return ITEM(`zeros ${sn(p)} and ${sn(q)}, and the graph passes through (${sn(x0)}, ${sn(peval(c,x0))})`,`y = ${poly(c)}`)}const xs=[-1,0,1,2];return ITEM(`table — x: ${xs.map(sn).join(', ')}  |  y: ${xs.map(x=>sn(peval(c,x))).join(', ')}`,`y = ${poly(c)}`)}};
J.reducible={fam:'j_alg',instr:'Solve. Write all real solutions.',work:true,g:(r,L)=>{const S=shuf(r,[1,2,3,4]).slice(0,2);const p=S[0]*S[0];let q=S[1]*S[1];if(L==='E'&&r()<.5)q=-q;const c=[1,0,-(p+q),0,p*q];const sols=[S[0],-S[0]].concat(q>0?[S[1],-S[1]]:[]).sort((a,b)=>a-b);return ITEM(`${poly(c)} = 0`,`Let u = x²: u = ${p} or u = ${sn(q)}; x = ${sols.map(sn).join(', ')}${q<0?' (u = '+sn(q)+' gives no real x)':''}`)}};
J.qmaxprob={fam:'j_alg',instr:'Solve. Show your solution.',work:true,g:(r,L)=>{const t=ri(r,0,2);if(t===0){const P=4*ri(r,5,30);return ITEM(`A farmer has ${P} m of fencing to enclose a rectangular garden. What dimensions give the largest area? What is that area?`,`A = x(${P/2} − x); maximum at x = ${P/4}; ${P/4} m by ${P/4} m; area ${fmt(P*P/16)} sq. m`)}
  if(t===1){const P=4*ri(r,5,25);return ITEM(`A rectangular pen is built against a wall, so only three sides need fencing. There is ${P} m of fencing. Find the largest possible area.`,`A = x(${P} − 2x); maximum at x = ${P/4} m; the side parallel to the wall is ${P/2} m; area ${fmt(P*P/8)} sq. m`)}
  const S=2*ri(r,5,30);return ITEM(`Two numbers add up to ${S}. What is the largest possible product?`,`P = x(${S} − x); maximum at x = ${S/2}; product ${fmt(S*S/4)}`)}};
J.radeq={fam:'j_alg',instr:'Solve each radical equation. Check for extraneous roots.',work:true,g:(r,L)=>{if(L!=='E'){const b=ri(r,1,9),a=ri(r,-10,10);const k=L==='F'?1:pick(r,[1,2,3]);const x=b*b-a;if(x%k)return J.radeq.g(r,L);return ITEM(`√(${lin(k,a)}) = ${b}`,`x = ${sn(x/k)}`)}
  for(let i=0;i<200;i++){const b=ri(r,0,5),r1=ri(r,b+2,b+8);const r2=2*b+1-r1;if(r2>=b)continue;const a=b*b-r1*r2;if(r1+a<0)continue;if(Math.sqrt(r1+a)!==r1-b)continue;return ITEM(`√(${lin(1,a)}) = ${lin(1,-b)}`.replace(/\(x\)/,'x'),`x = ${r1} (x = ${sn(r2)} is extraneous)`)}return ITEM('√(x + 7) = x − 5','x = 9 (x = 2 is extraneous)')}};
J.circform={fam:'j_geom',instr:'Rewrite the equation of each circle as asked.',work:true,g:(r,L)=>{const h=ri(r,-6,6),k=ri(r,-6,6),R=ri(r,1,9);const D=-2*h,E=-2*k,F=h*h+k*k-R*R;const cr=`(x ${h<0?'+ '+(-h):MN+' '+h})² + (y ${k<0?'+ '+(-k):MN+' '+k})² = ${R*R}`.replace(/\(x − 0\)/,'x').replace(/\(y − 0\)/,'y');const gen=`x² + y²${D?(D>0?' + '+D+'x':' '+MN+' '+(-D)+'x'):''}${E?(E>0?' + '+E+'y':' '+MN+' '+(-E)+'y'):''}${F?(F>0?' + '+F:' '+MN+' '+(-F)):''} = 0`;
  return r()<.5?ITEM(`Write ${cr} in general form.`,gen):ITEM(`Write ${gen} in center-radius form.`,cr)}};
J.circcr={fam:'j_geom',instr:'Find the center and radius of each circle.',work:true,g:(r,L)=>{const h=ri(r,-7,7),k=ri(r,-7,7),R=ri(r,1,10);if(L==='F')return ITEM(`(x ${h<0?'+ '+(-h):MN+' '+h})² + (y ${k<0?'+ '+(-k):MN+' '+k})² = ${R*R}`.replace(/\(x − 0\)/,'x').replace(/\(y − 0\)/,'y'),`center (${sn(h)}, ${sn(k)}); radius ${R}`);const D=-2*h,E=-2*k,F=h*h+k*k-R*R;return ITEM(`x² + y²${D?(D>0?' + '+D+'x':' '+MN+' '+(-D)+'x'):''}${E?(E>0?' + '+E+'y':' '+MN+' '+(-E)+'y'):''}${F?(F>0?' + '+F:' '+MN+' '+(-F)):''} = 0`,`center (${sn(h)}, ${sn(k)}); radius ${R}`)}};
const crForm=(h,k,R2)=>`(x ${h<0?'+ '+(-h):MN+' '+h})² + (y ${k<0?'+ '+(-k):MN+' '+k})² = ${R2}`.replace(/\(x − 0\)/,'x').replace(/\(y − 0\)/,'y');
J.circcond={fam:'j_geom',instr:'Find the equation of each circle in center-radius form.',work:true,g:(r,L)=>{const h=ri(r,-5,5),k=ri(r,-5,5);const t=L==='F'?0:ri(r,0,2);
  if(t===0){const R=ri(r,1,9);return ITEM(`center (${sn(h)}, ${sn(k)}), radius ${R}`,crForm(h,k,R*R))}
  if(t===1){const dx=ri(r,-5,5),dy=ri(r,-5,5)||1;return ITEM(`center (${sn(h)}, ${sn(k)}), passing through (${sn(h+dx)}, ${sn(k+dy)})`,crForm(h,k,dx*dx+dy*dy))}
  const T=pick(r,PYT.slice(0,4));const s=r()<.5;const dx=s?T[0]:T[1],dy=s?T[1]:T[0];return ITEM(`the endpoints of a diameter are (${sn(h-dx)}, ${sn(k-dy)}) and (${sn(h+dx)}, ${sn(k+dy)})`,`center (${sn(h)}, ${sn(k)}), radius ${T[2]}: ${crForm(h,k,T[2]*T[2])}`)}};
